#!/bin/bash
set -e

# Payments Dashboard -- replaces the 'coming soon' placeholder.
# Hero band: today's collection total, day-open status, payment-mode
# composition. Supporting stats: transactions today, outstanding dues,
# advance balances held. Revenue by department (bar chart, CSS-only,
# no new dependency). Recent transactions. Largest outstanding dues
# and largest advance balances as 'needs attention' panels.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/payments"
echo "" | base64 -d > "app/(main)/payments/actions.js"
echo "Wrote app/(main)/payments/actions.js"

mkdir -p "app/(main)/payments"
echo "" | base64 -d > "app/(main)/payments/page.js"
echo "Wrote app/(main)/payments/page.js"

git add "app/(main)/payments/actions.js" "app/(main)/payments/page.js"
git commit -m "Build Payments Dashboard: collection hero, stats, department breakdown, recent activity, attention panels"
git push

echo "Done."
